// Generated by npm run build:sw; commit sw.js with every shell change.
const CACHE='classic-win-games-57c8157b01ad7334';
const ASSETS=['./','./index.html','./style.css','./manifest.webmanifest','./src/cards.js','./src/klondike.js','./src/app.js','./src/version.js','./src/about.js','./build-info.json','./src/board.js','./src/freecell.js','./src/spider.js','./src/hints.js','./src/hearts.js','./src/minesweeper.js','./src/minesweeper-ui.js','./src/hearts-ui.js','./src/shortcuts.js','./src/history.js','./icons/icon-192.png','./icons/icon-512.png'];
const shell=new Set(ASSETS.map(path=>new URL(path,self.registration.scope).href));
self.addEventListener('install',event=>event.waitUntil((async()=>{
  const cache=await caches.open(CACHE);
  // Bypass HTTP caches when staging a complete new shell.
  await cache.addAll([...shell].map(url=>new Request(url,{cache:'reload'})));
  await self.skipWaiting();
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
  const keys=await caches.keys();
  await Promise.all(keys.filter(k=>k.startsWith('classic-win-games-')&&k!==CACHE).map(k=>caches.delete(k)));
  await self.clients.claim();
})()));
self.addEventListener('fetch',event=>{
  const url=new URL(event.request.url);
  // Fragments select a game, not a different cached document. FetchEvent
  // requests can retain them even though HTTP never sends them to the server.
  url.hash='';
  if(event.request.method!=='GET'||!shell.has(url.href))return;
  // Each running version uses one complete shell, online and offline. An updated
  // worker stages the next shell; controllerchange reloads persisted games.
  event.respondWith((async()=>{
    const cache=await caches.open(CACHE);
    return await cache.match(url.href)||fetch(event.request);
  })());
});
